-- Migration: Year 2 - Hematology Pathology MCQs Part 4 (121-160)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- HODGKIN LYMPHOMA (121-135)
    (v_topic_id, 'Hodgkin Lymphoma (HL) is defined by the presence of which pathognomonic cell?', '["Smudge cells", "Reed-Sternberg (RS) cells: large binucleated cells with prominent owl-eye nucleoli surrounded by a clear halo", "Auer rods", "Starry-sky macrophages"]', 1, 'Reed-Sternberg cells are the neoplastic cells of Hodgkin Lymphoma. They are derived from B-lymphocytes but have lost B-cell markers. Classic RS cells are binucleate (mirror-image nuclei) with large, prominent eosinophilic nucleoli (owl eyes), sitting in an inflammatory background.'),
    (v_topic_id, 'What is the immunophenotype of the classic Reed-Sternberg cell?', '["CD20+, CD15-, CD30-", "CD15+, CD30+, CD20-, CD45- (lacks pan-B and pan-leukocyte markers)", "CD3+, CD4+, CD8-", "CD20+, CD10+, BCL2+"]', 1, 'Classic RS cells: CD15+ and CD30+ (key positive markers) but CD20- and CD45- (lost pan-B and leukocyte markers). This immunophenotype distinguishes HL from NHL. CD30 (Ki-1 antigen) is targeted by brentuximab vedotin (antibody-drug conjugate).'),
    (v_topic_id, 'Hodgkin Lymphoma classically spreads in which pattern?', '["Hematogenously to distant organs first", "Contiguously from one lymph node group to adjacent groups (step-by-step, predictable spread)", "Via lymphatics to liver and spleen simultaneously", "Randomly to any lymph node group"]', 1, 'HL spreads contiguously — from one lymph node group to the next adjacent group in an orderly, predictable fashion (cervical → mediastinal → para-aortic → inguinal). This is why radiation therapy is effective for localized disease and why Ann Arbor staging drives treatment.'),
    (v_topic_id, 'Which subtype of Hodgkin Lymphoma has the BEST prognosis?', '["Mixed cellularity", "Lymphocyte-depleted", "Nodular sclerosis", "Lymphocyte-rich (classical HL) or Nodular lymphocyte predominant HL (NLPHL)"]', 3, 'Lymphocyte-rich HL and NLPHL have the best prognosis (many lymphocytes trying to suppress tumor). Nodular sclerosis is most common overall (young women, mediastinal mass). Mixed cellularity has intermediate prognosis. Lymphocyte-depleted is the rarest and worst prognosis.'),
    (v_topic_id, 'Nodular Sclerosis is the most common subtype of Hodgkin Lymphoma. What are its characteristic features?', '["Predominantly affects elderly men; RS cells surrounded by lymphocytes", "Presents in young women with mediastinal (anterior) mass; collagen bands divide lymph node into nodules; contains lacunar variant RS cells", "Diffuse effacement with depleted lymphocytes; worst prognosis", "Associated with EBV in 70% of cases; mixed inflammatory background"]', 1, 'Nodular sclerosis HL: young women (bimodal age 15-35 and >55) + anterior mediastinal mass (can cause SVC syndrome) + collagen bands forming nodules on biopsy + lacunar variant RS cells (RS cells with retracted cytoplasm appearing to sit in a lacuna). Most common subtype (~70%).'),
    (v_topic_id, 'Which subtype of Hodgkin Lymphoma has the strongest association with Epstein-Barr Virus (EBV)?', '["Nodular sclerosis", "Lymphocyte predominant", "Mixed cellularity (EBV+ in ~75% of cases)", "Nodular lymphocyte predominant"]', 2, 'Mixed cellularity HL is most strongly EBV-associated (EBV-encoded LMP1 oncogene drives RS cell survival). Mixed cellularity: mixed inflammatory background (lymphocytes, eosinophils, plasma cells, histiocytes) + classic RS cells + older patients + lower socioeconomic status + more often presents with B symptoms.'),
    (v_topic_id, 'Nodular Lymphocyte Predominant HL (NLPHL) is distinct from classical HL. What is its unique neoplastic cell?', '["Classic Reed-Sternberg cells", "Popcorn cells (LP cells): large cells with multilobated nuclei resembling popcorn, CD20+ CD15- CD30-", "Lacunar cells", "Smudge cells"]', 1, 'NLPHL: Popcorn cells (LP cells = lymphocytic and histiocytic cells). Unlike classic HL, popcorn cells are CD20+ (retained B-cell marker), CD15-, CD30-. NLPHL is more indolent, has excellent prognosis, but can transform to DLBCL.'),
    (v_topic_id, 'B symptoms in Hodgkin Lymphoma are defined as?', '["Night sweats, unintentional weight loss >10% in 6 months, and unexplained fever >38 degrees C", "Bone pain, back pain, and bilateral arm swelling", "Bilateral leg edema, ascites, and jaundice", "Pruritus, fatigue, and anemia"]', 0, 'B symptoms (constitutional symptoms): fever >38C, drenching night sweats, and weight loss >10% body weight in 6 months. Their presence upgrades the clinical stage from A to B (e.g., Stage IIA → Stage IIB) and worsens prognosis. Not the same as the non-specific fatigue/pruritus.'),
    (v_topic_id, 'The Ann Arbor staging system for lymphoma is based on which principle?', '["Tumor histology and grade", "Number of lymph node groups involved and whether disease is on one or both sides of the diaphragm, and extranodal involvement", "Bone marrow biopsy findings", "Serum LDH level"]', 1, 'Ann Arbor: Stage I = one lymph node region; Stage II = 2+ regions, same side of diaphragm; Stage III = regions on BOTH sides of diaphragm; Stage IV = diffuse extranodal involvement (bone marrow, liver). E suffix = extranodal; S = spleen; A/B = absence/presence of B symptoms.'),
    (v_topic_id, 'First-line chemotherapy for classical Hodgkin Lymphoma is?', '["CHOP (cyclophosphamide, doxorubicin, vincristine, prednisone)", "ABVD (Adriamycin, Bleomycin, Vinblastine, Dacarbazine)", "R-CHOP (rituximab + CHOP)", "BEP (bleomycin, etoposide, cisplatin)"]', 1, 'ABVD is the standard first-line regimen for classical HL. It replaced MOPP (which was highly mutagenic). Rituximab is NOT used for classical HL because RS cells are CD20-. ABVD toxicities: Adriamycin = cardiotoxicity; Bleomycin = pulmonary fibrosis.'),
    (v_topic_id, 'A 25-year-old woman presents with cervical lymphadenopathy and a large anterior mediastinal mass. She has no fever but reports night sweats. Biopsy shows collagen bands and lacunar variant RS cells. Diagnosis and stage?', '["Mixed cellularity HL, Stage IIA", "Nodular Sclerosis HL, Stage IIA (2 sites, one side of diaphragm, night sweats = B symptom)", "Lymphocyte-depleted HL, Stage IVB", "Nodular Sclerosis HL, Stage IIB"]', 3, 'Nodular sclerosis (young woman + anterior mediastinal mass + lacunar RS cells). Two sites (cervical + mediastinal) = Stage II. Night sweats = B symptom → Stage IIB. Fever would also make it B.'),
    (v_topic_id, 'The Pel-Ebstein fever pattern is classically associated with which condition?', '["Multiple myeloma", "Hodgkin Lymphoma (cyclic fever with days to weeks of fever alternating with afebrile periods)", "CML", "Malaria"]', 1, 'Pel-Ebstein fever: characteristic cyclic fever pattern in HL (and occasionally Brucellosis). Fever rises and falls in a regular pattern over days to weeks, alternating with asymptomatic intervals. It is one of the B symptoms.'),
    (v_topic_id, 'Brentuximab vedotin is a novel therapy for relapsed/refractory Hodgkin Lymphoma. What is its target?', '["CD20 on B-cells", "CD30 on Reed-Sternberg cells (antibody-drug conjugate delivering monomethyl auristatin E)", "CD52 on lymphocytes", "VEGF"]', 1, 'Brentuximab vedotin: anti-CD30 antibody linked to the microtubule-disrupting toxin MMAE. CD30 is consistently expressed on RS cells in classical HL (and on ALCL). The antibody delivers the toxin selectively to CD30+ cells.'),
    (v_topic_id, 'Which is more common in HIV patients with lymphoma: Hodgkin or Non-Hodgkin Lymphoma?', '["Hodgkin Lymphoma (3x more common)", "Non-Hodgkin Lymphoma (particularly aggressive types like DLBCL, Burkitt, and primary CNS lymphoma)", "Equal frequency", "Primary CNS lymphoma only"]', 1, 'HIV markedly increases risk of NHL (particularly aggressive B-cell lymphomas: DLBCL, Burkitt, primary CNS lymphoma). AIDS-defining malignancy = primary CNS lymphoma (associated with EBV). HL also increases in HIV but less so than NHL.'),
    (v_topic_id, 'Long-term complications of ABVD chemotherapy for Hodgkin Lymphoma include?', '["Only infertility", "Secondary AML (from alkylating agents), pulmonary fibrosis (bleomycin), cardiac disease (doxorubicin), and secondary solid tumors", "Only peripheral neuropathy", "Only alopecia"]', 1, 'ABVD toxicities: Bleomycin = pulmonary fibrosis (check DLCO before each cycle). Doxorubicin (Adriamycin) = dilated cardiomyopathy. Secondary malignancies (AML, solid tumors at radiation field including breast cancer in women) are major long-term concerns.'),

    -- NON-HODGKIN LYMPHOMA (136-160)
    (v_topic_id, 'The most common Non-Hodgkin Lymphoma in adults in the United States is?', '["Follicular lymphoma", "Diffuse Large B-Cell Lymphoma (DLBCL)", "Burkitt lymphoma", "Mantle cell lymphoma"]', 1, 'DLBCL accounts for ~30-35% of all NHL. It is an aggressive B-cell lymphoma that requires prompt treatment. Presents with rapidly enlarging lymphadenopathy, often with extranodal involvement. Treated with R-CHOP (rituximab + CHOP chemotherapy).'),
    (v_topic_id, 'The most common INDOLENT (low-grade) Non-Hodgkin Lymphoma is?', '["Mantle cell lymphoma", "Follicular lymphoma", "CLL/SLL", "Marginal zone lymphoma"]', 1, 'Follicular lymphoma is the most common indolent NHL (~20% of all NHL). It is incurable with standard therapy but responds well and has long median survival (10+ years). The hallmark: t(14;18) translocation causing BCL2 overexpression, preventing apoptosis of follicular B-cells.'),
    (v_topic_id, 'Follicular lymphoma is characterized by which translocation?', '["t(8;14) — c-MYC and IgH", "t(14;18) — BCL2 and IgH (BCL2 overexpression prevents apoptosis of germinal center B-cells)", "t(11;14) — BCL1/Cyclin D1 and IgH", "t(9;22) — BCR-ABL"]', 1, 'In follicular lymphoma, BCL2 (anti-apoptotic protein) is translocated to the IgH locus on chromosome 14, causing constitutive overexpression. BCL2 blocks apoptosis, allowing neoplastic follicular B-cells to accumulate despite normal cell cycle. Paradoxically, follicular lymphoma has a low Ki-67 (slow growing).'),
    (v_topic_id, 'A hallmark of follicular lymphoma on biopsy is that it maintains a follicular growth pattern. What is the clinical behavior pattern that distinguishes it from more aggressive lymphomas?', '["It is rapidly fatal without treatment", "It is indolent (waxing and waning lymphadenopathy) but ultimately incurable; it can transform to DLBCL (Richter-like transformation)", "It only affects extranodal sites", "It responds poorly to rituximab"]', 1, 'Follicular lymphoma: patients often notice lymph nodes swelling and shrinking over years. It responds to treatment but invariably relapses. In ~30-40% of cases, it undergoes histologic transformation to the more aggressive DLBCL, which requires aggressive rescue therapy.'),
    (v_topic_id, 'Diffuse Large B-Cell Lymphoma (DLBCL) is treated with which standard regimen?', '["ABVD", "R-CHOP (Rituximab + Cyclophosphamide + Hydroxydaunorubicin + Vincristine + Prednisone)", "Imatinib alone", "Brentuximab vedotin"]', 1, 'R-CHOP is the backbone of DLBCL treatment. Rituximab (anti-CD20 monoclonal antibody) is added to CHOP chemotherapy because DLBCL cells are CD20+. R-CHOP cures ~60% of patients with DLBCL (compared to CHOP alone at ~30-40% cure rate).'),
    (v_topic_id, 'Burkitt Lymphoma has the fastest doubling time of any human tumor. What is the characteristic translocation?', '["t(14;18) — BCL2", "t(8;14) — c-MYC oncogene translocated to IgH locus (less commonly t(8;22) or t(2;8))", "t(11;14) — BCL1/Cyclin D1", "t(15;17) — PML-RARA"]', 1, 'Burkitt lymphoma: t(8;14) places c-MYC (chromosome 8) under control of IgH enhancer on chromosome 14. c-MYC is the master transcription factor for cell proliferation. Uncontrolled c-MYC expression drives explosive tumor growth (Ki-67 = ~100%).'),
    (v_topic_id, 'Histologically, Burkitt Lymphoma shows a starry-sky pattern. What creates the stars?', '["Reed-Sternberg cells surrounded by lymphocytes", "Macrophages (tingible-body macrophages) engulfing rapidly dying tumor cells, creating pale macrophage stars against a dark blue lymphocyte sky", "Plasma cells surrounded by small lymphocytes", "Eosinophils scattered among large cells"]', 1, 'In Burkitt lymphoma, the extremely high proliferation rate is matched by an equally high cell death rate. Tingible-body macrophages (macrophages with engulfed debris of dead tumor cells) scatter among the dense sheets of neoplastic B-cells, creating a starry-sky appearance.'),
    (v_topic_id, 'Which form of Burkitt Lymphoma is associated with EBV infection and classically presents as a jaw tumor in African children?', '["Sporadic Burkitt lymphoma (abdominal mass)", "Endemic Burkitt lymphoma (African/EBV-associated): jaw/facial bones most common site", "Immunodeficiency-associated Burkitt lymphoma", "Primary CNS Burkitt lymphoma"]', 1, 'Endemic (African) Burkitt: nearly 100% EBV-associated; jaw/orbit most common sites in children age 4-7. EBV likely acts as a cofactor, enabling c-MYC translocation events. Sporadic Burkitt: abdominal mass (ileocecal region most common); 15-20% EBV-associated.'),
    (v_topic_id, 'Mantle Cell Lymphoma is an aggressive B-cell lymphoma with a characteristic translocation. Which is it?', '["t(14;18) — BCL2", "t(11;14) — Cyclin D1 (BCL1) and IgH, overexpressing cyclin D1 and driving uncontrolled G1-to-S phase entry", "t(8;14) — c-MYC", "t(9;22) — BCR-ABL"]', 1, 'Mantle cell lymphoma: t(11;14) overexpresses Cyclin D1, the key regulator of the G1/S cell cycle checkpoint. Cyclin D1 complexes with CDK4/6, phosphorylating and inactivating Rb, releasing E2F to drive S-phase entry. Mantle cell has an intermediate prognosis (worse than follicular, better than Burkitt).'),
    (v_topic_id, 'Mantle cell lymphoma has a characteristic immunophenotype. Which marker combination is diagnostic?', '["CD20+, CD5+, CD23-, Cyclin D1+", "CD20+, CD5-, CD23+, BCL2+", "CD20-, CD5+, CD30+", "CD3+, CD4+, CD30+"]', 0, 'Mantle cell: CD20+ (B-cell) + CD5+ (co-expressed, unusual for B-cells — shared with CLL) + CD23- (distinguishes from CLL, which is CD23+) + Cyclin D1+ (nuclear stain, highly specific). This panel is pathognomonic.'),
    (v_topic_id, 'Primary CNS Lymphoma (PCNSL) in an immunocompromised (HIV/AIDS) patient is virtually always associated with which virus?', '["CMV", "EBV (Epstein-Barr Virus)", "HHV-8", "JC Virus"]', 1, 'PCNSL in AIDS patients is virtually 100% EBV-associated (EBV-driven DLBCL in the CNS). It is an AIDS-defining malignancy. Presents with focal neurological deficits, seizures, or cognitive decline. MRI shows ring-enhancing lesion(s) — must distinguish from cerebral toxoplasmosis.'),
    (v_topic_id, 'MALT lymphoma (Mucosa-Associated Lymphoid Tissue lymphoma) of the stomach is associated with which organism?', '["Clostridium difficile", "Helicobacter pylori infection driving chronic gastric B-cell stimulation", "EBV", "CMV"]', 1, 'Gastric MALT lymphoma: H. pylori chronically stimulates gastric B-cells → over time, antigen-driven stimulation leads to monoclonal B-cell proliferation. Early-stage MALT lymphoma can be CURED by H. pylori eradication alone (antibiotics + PPI). Advanced stage requires rituximab and/or radiation.'),
    (v_topic_id, 'Mycosis Fungoides is a T-cell lymphoma with unique features. Where does it preferentially localize?', '["Bone marrow and peripheral blood", "Skin (epidermotropic CD4+ T-cell lymphoma), with progression to lymph nodes and visceral organs in advanced stages", "Lymph nodes only", "Gastrointestinal tract"]', 1, 'Mycosis Fungoides is the most common cutaneous T-cell lymphoma. Neoplastic CD4+ T-helper cells infiltrate the skin. Progression: patch stage → plaque stage → tumor stage → Sezary syndrome (leukemic phase with cerebriform Sezary cells in blood). Histology: Pautrier microabscesses (lymphocytes within epidermis).'),
    (v_topic_id, 'Sezary Syndrome is the leukemic phase of Mycosis Fungoides. The characteristic cells in peripheral blood are?', '["Smudge cells with soccer ball chromatin", "Sezary cells: large T-cells with deeply cerebriform (convoluted, brain-like) nuclei", "Reed-Sternberg cells in blood", "Hairy cells with TRAP staining"]', 1, 'Sezary cells have characteristic cerebriform nuclei (deeply grooved, resembling a brain or walnut). Sezary syndrome triad: erythroderma (full-body skin redness), generalized lymphadenopathy, and >1000 Sezary cells/mcL in peripheral blood.'),
    (v_topic_id, 'Anaplastic Large Cell Lymphoma (ALCL) is a T-cell lymphoma characterized by which translocation in the systemic form?', '["t(14;18) — BCL2", "t(2;5) — NPM-ALK fusion, producing the ALK oncogenic kinase", "t(8;14) — c-MYC", "t(11;14) — Cyclin D1"]', 1, 'ALK-positive ALCL: t(2;5) creates NPM-ALK fusion gene. ALK kinase drives uncontrolled T-cell proliferation. ALCL cells: large anaplastic cells, often horseshoe or embryo-shaped nuclei, CD30+. ALK-positive ALCL has BETTER prognosis than ALK-negative ALCL. Treated with brentuximab vedotin (anti-CD30).'),
    (v_topic_id, 'Marginal Zone Lymphoma includes three subtypes. The extranodal type (MALT) is the most common. What is the nodal form called?', '["Hairy cell leukemia", "Splenic marginal zone lymphoma", "Nodal marginal zone lymphoma (monocytoid B-cell lymphoma) — a rare indolent B-cell lymphoma involving lymph nodes", "Waldenstroms macroglobulinemia"]', 2, 'Marginal zone lymphoma subtypes: (1) Extranodal MALT (gastric, lung, thyroid, salivary gland — driven by chronic inflammation/infection); (2) Splenic MZL (involves spleen + peripheral blood); (3) Nodal MZL (lymph node-based, rarest form). All are indolent CD20+ B-cell lymphomas.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
